import{_ as e,o as t,c as o,a4 as i}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"ZTE B860AV1.1-T2 工作记录","description":"","frontmatter":{"title":"ZTE B860AV1.1-T2 工作记录","date":"2026-07-27T00:00:00.000Z"},"headers":[],"relativePath":"posts/zeb860_cleanup_log.md","filePath":"posts/zeb860_cleanup_log.md"}'),r={name:"posts/zeb860_cleanup_log.md"};function l(s,a,n,c,h,d){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="zte-b860av1-1-t2-工作记录" tabindex="-1">ZTE B860AV1.1-T2 工作记录 <a class="header-anchor" href="#zte-b860av1-1-t2-工作记录" aria-label="Permalink to &quot;ZTE B860AV1.1-T2 工作记录&quot;">​</a></h1><h2 id="_2026-07-27-清理-home-目录污染文件" tabindex="-1">2026-07-27 清理 home 目录污染文件 <a class="header-anchor" href="#_2026-07-27-清理-home-目录污染文件" aria-label="Permalink to &quot;2026-07-27 清理 home 目录污染文件&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>工作站 <code>/home/a1/</code> 被 ZTE 盒子的文件污染（1970年1月1日时间戳），是之前 adb push/rootfs 操作时意外带入的。</p><h3 id="已移入回收站的文件-23个" tabindex="-1">已移入回收站的文件（23个） <a class="header-anchor" href="#已移入回收站的文件-23个" aria-label="Permalink to &quot;已移入回收站的文件（23个）&quot;">​</a></h3><p>路径：<code>/home/a1/.trash/</code></p><p><strong>init 相关：</strong> init, init.rc, init.zxic.rc, init.environ.rc, init.product.rc, init.trace.rc, init.usb.rc, initlogo.rle</p><p><strong>SELinux/属性：</strong> default.prop, fstab.zxic, file_contexts, property_contexts, seapp_contexts, sepolicy</p><p><strong>ueventd/ZTE配置：</strong> ueventd.rc, ueventd.zxic.rc, zte_init.rc, zte_middleware.rc</p><p><strong>空目录：</strong> data/, dev/, proc/, sys/, system/</p><h3 id="保留的文件" tabindex="-1">保留的文件 <a class="header-anchor" href="#保留的文件" aria-label="Permalink to &quot;保留的文件&quot;">​</a></h3><ul><li>boot/mali.ko - GPU驱动</li><li>sbin/ - adbd, healthd, hostapd_7601, iwconfig, iwlist, wpa_supplicant_7601</li><li>sh/, usr/ - 用户脚本和bin</li><li>easytier-linux-x86_64/, HiTool/, zte_b860_docs/</li></ul><h3 id="恢复方法" tabindex="-1">恢复方法 <a class="header-anchor" href="#恢复方法" aria-label="Permalink to &quot;恢复方法&quot;">​</a></h3><p>mv /home/a1/.trash/* /home/a1/</p><hr><h2 id="当前设备状态" tabindex="-1">当前设备状态 <a class="header-anchor" href="#当前设备状态" aria-label="Permalink to &quot;当前设备状态&quot;">​</a></h2><h3 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h3><p>system 分区缺失 5 个关键 .so：libc.so, libcrypto.so, libcorkscrew.so, libbinder.so, libkeystore_binder.so 系统无法正常启动，卡在 CANNOT LINK EXECU 循环。</p><h3 id="修复计划" tabindex="-1">修复计划 <a class="header-anchor" href="#修复计划" aria-label="Permalink to &quot;修复计划&quot;">​</a></h3><p>将 OTA.zip (247MB) 写入 cache 分区 (ext4, 768MB)，safe 进 recovery 刷机。</p><h3 id="tftp-传输参数" tabindex="-1">TFTP 传输参数 <a class="header-anchor" href="#tftp-传输参数" aria-label="Permalink to &quot;TFTP 传输参数&quot;">​</a></h3><ul><li>块大小：5MB (5242880 字节 = 10240 扇区 = 0x2800)</li><li>cache 分区起始扇区：0x3C000</li><li>U-Boot: tftpboot 0x48000000 c_xx → mmc write 0x48000000 &lt;扇区&gt; 0x2800</li></ul><h3 id="关键教训" tabindex="-1">关键教训 <a class="header-anchor" href="#关键教训" aria-label="Permalink to &quot;关键教训&quot;">​</a></h3><ol><li>不要盲目删 .so 文件 - 误删 libkeystore_binder.so 导致系统无法启动</li><li>TFTP 5MB 是稳定上限，需分块</li><li>U-Boot source 不支持纯文本脚本</li><li>ext4 镜像 mkfs 参数需与原始分区一致</li></ol>',24)])])}const b=e(r,[["render",l]]);export{u as __pageData,b as default};
